en_names={'Auspícios':'Auspex','Dominação':'Dominate','Animalismo':'Animalism','Ofuscação':'Obfuscate','Proteanismo':'Protean','Oblívio':'Oblivion','Feitiçaria de Sangue':'Blood Sorcery','Alquimia do Sangue-Fraco':'Thin-Blood Alchemy','Celeridade':'Celerity','Potência':'Potence'}
for book,data,offset in [('sabbat-black-hand-v5',sabbat,1),('gehenna-war-v5',gehenna,2)]:
 source=next(x for x in manifest if x['id']==book)
 boundaries=[row[0].upper() for row in data]
 for name,pt,kind,discipline,level,numbers,amalgam,groups,rows in data:
  raw='\n\n'.join(json.loads((work/'pages'/book/f'{n:04}.json').read_text(encoding='utf-8'))['content'] for n in numbers)
  raw=raw.split('## '+name.upper()+'\n',1)[1]
  raw=re.split(r'\n## (?:'+'|'.join(re.escape(t) for t in boundaries)+r'|Level \d|Animalism|Auspex|Celerity|Dominate|Fortitude|Obfuscate|Potence|Protean|Oblivion|Blood Sorcery(?: Rituals)?|Rituals|Ceremonies|Oblivion Ceremony|Thin-Blood Alchemy)\n',raw,1)[0]
  raw=re.sub(r'^##\s+', '',raw,flags=re.M)
  raw=raw.replace('Vampire:\n\nThe Masquerade','Vampire: The Masquerade').replace('Mas-\n\nquerade','Masquerade').replace('some-\n\none','someone')
  raw=re.sub(r'(?<=[a-z,])\n\n(?=[a-z])',' ',raw)
  raw=re.sub(r'(?<!\n)( Dice Pools?:)',r'\n\n\1',raw)
  parts=re.split(r'(?:^|\n\n)(Cost|Dice Pools?|Ingredients?|Process|System|Duration|Activation Cost|Note):\s*',raw)
  english=[{'title':'Description','text':parts[0].strip()}]
  for i in range(1,len(parts),2):english.append({'title':parts[i],'text':parts[i+1].strip()})
  required={discipline:level}|amalgam
  english.insert(1,{'title':'Requirements','text':'; '.join(f'{en_names.get(d,d)} {n}' for d,n in required.items())+('. Powers: '+'; '.join(' or '.join(group) for group in groups) if groups else '')+'.'})
  portuguese=[{'title':t,'text':v} for t,v in rows]
  portuguese.insert(1,{'title':'Requisitos','text':'; '.join(f'{d} {n}' for d,n in required.items())+'.'})
  if name=='Befoul Vessel':english.append({'title':'Source reference ambiguity','text':'The source names Necrotic Touch as a prerequisite without identifying that power here. This reference is preserved rather than silently replaced with Touch of Oblivion or Necrotic Plague; consult the Storyteller.'})
  if kind=='ritual':
   general=json.loads((repo/'scripts/reviewed-content/clinging-of-the-insect.json').read_text(encoding='utf-8'))['versions'][0]['descriptions']
   for locale,values in [('pt-BR',portuguese),('en',english)]:
    section=dict(general[locale][-1]);section['text']+='\n\n'+('[Original general rules](/rules/source?book=core-v5&page=274)' if locale=='en' else '[Página original das regras gerais](/rules/source?book=core-v5&page=274)');values.append(section)
  if kind=='ceremony':
   for locale,values in [('pt-BR',portuguese),('en',english)]:values.append({'title':'General Ceremony rules' if locale=='en' else 'Regras gerais de Cerimônias','text':f'Unless specifically overridden: one Rouse Check, {level*5} minutes, Resolve + Oblivion, Difficulty {level+1}. Learning costs {level*3} XP and requires Oblivion {level} and the prerequisite power. Learning during play requires a teacher and at least {level**2} weeks. Thin-bloods do not receive Ceremonies. Effects remain manually resolved.' if locale=='en' else f'Salvo exceção específica: um Teste de Sangue, {level*5} minutos, Determinação + Oblívio, Dificuldade {level+1}. Aprender custa {level*3} XP e exige Oblívio {level} e o poder pré-requisito. Durante o jogo, exige professor e ao menos {level**2} semanas. Sangues-ralos não recebem Cerimônias. Os efeitos são resolvidos manualmente.'})
  match=next((x for x in candidates if x['book']==book and x['name']==name),None)
  id=match['id'] if match else re.sub('[^a-z0-9]+','-',f'{book}-{kind}-{discipline}-{name}'.lower())
  requirements={'disciplines':required}
  if groups:requirements['prerequisiteAlternatives']=groups
  version={'id':id+'-'+book,'book':book,'level':level,'sourceTitle':('Sabbat: The Black Hand V5' if book.startswith('sabbat') else 'Gehenna War V5')+', PDF pp. '+', '.join(map(str,numbers)),'sourceLanguage':'en','pdfSha256':source['sha256'],'pages':[{'pdfPage':n,'printedPage':n-offset} for n in numbers],'requirements':requirements,'descriptions':{'pt-BR':portuguese,'en':english}}
  entry={'id':id,'kind':kind,'names':{'pt-BR':pt,'en':name},'aliases':[pt,name],'discipline':discipline,'level':level,'versions':[version]}
  (repo/'scripts/reviewed-content'/f'{id}.json').write_text(json.dumps(entry,ensure_ascii=False,indent=2),encoding='utf-8')
print('17 Sabbat and 19 Gehenna War entries prepared, including three missing formulae')
